const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel Organization {\n  id                         String               @id @default(cuid())\n  name                       String\n  slug                       String               @unique\n  logoUrl                    String?\n  legalName                  String?\n  vatNumber                  String?\n  fiscalCode                 String?\n  address                    String?\n  city                       String?\n  zip                        String?\n  country                    String?\n  phone                      String?\n  email                      String?\n  pec                        String?\n  sdiCode                    String?\n  aiMonthlyTokenLimit        Int                  @default(1800000)\n  aiTokensUsed               Int                  @default(0)\n  aiTokensResetAt            DateTime?\n  perplexityMonthlyLimit     Int                  @default(600)\n  perplexityRequestsUsed     Int                  @default(0)\n  perplexityRequestsResetAt  DateTime?\n  conflictMaxCleaningsPerDay Int                  @default(3)\n  conflictUrgentHours        Int                  @default(48)\n  conflictStaleTicketDays    Int                  @default(7)\n  conflictOverlapMinutes     Int                  @default(90)\n  createdAt                  DateTime             @default(now())\n  users                      User[]\n  apartments                 Apartment[]\n  properties                 Property[]\n  chatSessions               ManagerChatSession[]\n  engagements                Engagement[]\n  companyMessages            OrgCompanyMessage[]\n  staffMessages              OrgStaffMessage[]\n}\n\n// Struttura ricettiva (hotel/residence): indirizzo unico, contiene N unita'\n// raggruppate per categoria. L'appartamento singolo NON usa questo modello\n// (resta un Apartment senza propertyId), cosi' i due tipi convivono.\nmodel Property {\n  id             String            @id @default(uuid())\n  name           String\n  organizationId String?\n  organization   Organization?     @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  address        String\n  latitude       Float\n  longitude      Float\n  type           String            @default(\"RESIDENCE\") // \"HOTEL\" | \"RESIDENCE\"\n  createdAt      DateTime          @default(now())\n  categories     UnitCategory[]\n  units          Apartment[]\n  products       PropertyProduct[]\n\n  @@index([organizationId])\n}\n\n// Prodotto a livello di struttura: stock UNICO condiviso da tutte le unita'.\n// Il consumo al check-in viene definito per categoria (UnitCategory.consumption)\n// e sottratto da questo stock.\nmodel PropertyProduct {\n  id         String                  @id @default(uuid())\n  propertyId String\n  property   Property                @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  name       String\n  emoji      String                  @default(\"📦\")\n  unit       String                  @default(\"pz\")\n  stock      Int                     @default(0)\n  minStock   Int                     @default(0)\n  price      Float                   @default(0)\n  vat        Float                   @default(22)\n  createdAt  DateTime                @default(now())\n  updatedAt  DateTime                @updatedAt\n  movements  PropertyStockMovement[]\n\n  @@index([propertyId])\n}\n\nmodel PropertyStockMovement {\n  id        String          @id @default(uuid())\n  productId String\n  product   PropertyProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n  delta     Int\n  balance   Int\n  reason    String // INITIAL | CHECKIN | RESTOCK | ADJUSTMENT\n  bookingId String?\n  note      String?\n  createdAt DateTime        @default(now())\n\n  @@index([productId, createdAt])\n}\n\n// Categoria di unita' = \"master\": le caratteristiche condivise da tutte le\n// unita' che vi appartengono (mq, letti/biancheria, elettrodomestici, accessi).\n// Le unita' sono identiche al master; modificando il master si propaga a tutte\n// (con conferma esplicita lato UI).\nmodel UnitCategory {\n  id                 String      @id @default(uuid())\n  propertyId         String\n  property           Property    @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  name               String\n  squareMeters       Int\n  bedrooms           Int\n  bathrooms          Int\n  maxGuests          Int\n  bedConfig          Json?\n  technicalProfile   Json?\n  accessInstructions String?\n  accessInfo         Json?\n  consumption        Json? // { [propertyProductId]: quantita' consumata al check-in }\n  createdAt          DateTime    @default(now())\n  units              Apartment[]\n\n  @@index([propertyId])\n}\n\nmodel User {\n  id                   String                @id @default(uuid())\n  email                String                @unique\n  password             String\n  role                 Role\n  createdAt            DateTime              @default(now())\n  name                 String\n  phone                String?\n  address              String?\n  isExternal           Boolean               @default(false)\n  companyName          String?\n  vatNumber            String?\n  iban                 String?\n  organizationId       String?\n  notificationPrefs    Json?\n  failedLoginCount     Int                   @default(0)\n  lockedUntil          DateTime?\n  privacyAcceptedAt    DateTime?\n  companyId            String?\n  company              Company?              @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  organization         Organization?         @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  cleaningTasks        CleaningTask[]\n  maintenanceTickets   MaintenanceTicket[]\n  supervisorReviews    SupervisorReview[]    @relation(\"SupervisorReviews\")\n  supervisedApartments ApartmentSupervisor[]\n  ownedApartments      ApartmentOwner[]\n  pushSubscriptions    PushSubscription[]\n  apnsTokens           ApnsToken[]\n  fcmTokens            FcmToken[]\n  cleanerLocation      CleanerLocation?\n  checkinTasks         CheckinTask[]\n  orgStaffMessages     OrgStaffMessage[]     @relation(\"orgStaffMessages\")\n\n  @@index([organizationId])\n  @@index([companyId])\n}\n\n// Chat org ↔ impresa: un thread per (org, company). Visibile solo ai manager\n// dell'organizzazione e al manager dell'impresa. Manager-to-manager.\nmodel OrgCompanyMessage {\n  id              String       @id @default(uuid())\n  organizationId  String\n  companyId       String\n  senderIsOrg     Boolean\n  senderName      String\n  text            String\n  mediaUrl        String?\n  mediaType       String?\n  mediaName       String?\n  createdAt       DateTime     @default(now())\n  readByOrgAt     DateTime?\n  readByCompanyAt DateTime?\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  company         Company      @relation(fields: [companyId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, companyId, createdAt])\n}\n\n// Chat generica org ↔ staff diretto: un thread per (org, operatore).\n// Visibile solo al manager dell'organizzazione e all'operatore stesso.\nmodel OrgStaffMessage {\n  id              String       @id @default(uuid())\n  organizationId  String\n  staffUserId     String\n  senderIsManager Boolean\n  senderName      String\n  text            String?\n  mediaUrl        String?\n  mediaType       String?\n  mediaName       String?\n  createdAt       DateTime     @default(now())\n  readByManagerAt DateTime?\n  readByStaffAt   DateTime?\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  staffUser       User         @relation(\"orgStaffMessages\", fields: [staffUserId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, staffUserId, createdAt])\n}\n\n// Chat privata dell'impresa: un thread per (impresa, operatore). Visibile solo\n// al manager d'impresa e all'operatore stesso; MAI al proprietario.\nmodel CompanyChatMessage {\n  id              String    @id @default(uuid())\n  companyId       String\n  staffUserId     String\n  senderIsManager Boolean\n  text            String\n  mediaUrl        String?\n  mediaType       String? // image | audio | file (categoria) o mime\n  mediaName       String?\n  createdAt       DateTime  @default(now())\n  readByManagerAt DateTime?\n  readByStaffAt   DateTime?\n\n  @@index([companyId, staffUserId, createdAt])\n}\n\n// Impresa esterna indipendente (pulizie/manutenzione/check-in/supervisione).\n// Non e' figlia di una singola Organization: viene ingaggiata (Engagement) da\n// una o piu' organizzazioni, e puo' coprire piu' funzioni.\nmodel Company {\n  id                        String              @id @default(uuid())\n  name                      String\n  slug                      String              @unique\n  legalName                 String?\n  vatNumber                 String?\n  scopes                    String[]            @default([]) // funzioni offerte: CLEANING|MAINTENANCE|CHECKIN|SUPERVISION\n  aiMonthlyTokenLimit       Int                 @default(1800000)\n  aiTokensUsed              Int                 @default(0)\n  aiTokensResetAt           DateTime?\n  perplexityMonthlyLimit    Int                 @default(600)\n  perplexityRequestsUsed    Int                 @default(0)\n  perplexityRequestsResetAt DateTime?\n  createdAt                 DateTime            @default(now())\n  users                     User[]\n  engagements               Engagement[]\n  warehouseProducts         WarehouseProduct[]\n  orgMessages               OrgCompanyMessage[]\n}\n\n// Ingaggio: un proprietario (Organization) delega UNA funzione (scope) a una\n// Company. Consenso e revoca sono del proprietario.\nmodel Engagement {\n  id             String                @id @default(uuid())\n  organizationId String\n  companyId      String?\n  scope          String // CLEANING | MAINTENANCE | CHECKIN | SUPERVISION\n  status         String                @default(\"PENDING\") // PENDING | ACTIVE | REVOKED\n  inviteToken    String?               @unique\n  invitedAt      DateTime              @default(now())\n  acceptedAt     DateTime?\n  revokedAt      DateTime?\n  organization   Organization          @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  company        Company?              @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  apartments     EngagementApartment[]\n\n  @@unique([organizationId, companyId, scope])\n  @@index([companyId])\n  @@index([organizationId])\n}\n\nmodel EngagementApartment {\n  engagementId String\n  apartmentId  String\n  engagement   Engagement @relation(fields: [engagementId], references: [id], onDelete: Cascade)\n  apartment    Apartment  @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n\n  @@id([engagementId, apartmentId])\n  @@index([apartmentId])\n}\n\nmodel Apartment {\n  id                    String                 @id @default(uuid())\n  name                  String\n  apartmentCode         String?                @unique\n  organizationId        String?\n  organization          Organization?          @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  address               String\n  latitude              Float\n  longitude             Float\n  squareMeters          Int\n  bedrooms              Int\n  bathrooms             Int\n  maxGuests             Int\n  accessInstructions    String?\n  accessInfo            Json?\n  bedConfig             Json?\n  icalUrl               String?\n  lastSyncAt            DateTime?\n  technicalProfile      Json?\n  checkinDefaultTime    String?\n  autoCheckin           Boolean                @default(false)\n  createdAt             DateTime               @default(now())\n  clientId              String?\n  client                Client?                @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  propertyId            String?\n  property              Property?              @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  unitCategoryId        String?\n  unitCategory          UnitCategory?          @relation(fields: [unitCategoryId], references: [id], onDelete: SetNull)\n  unitNumber            String?\n  bookings              Booking[]\n  checklistItems        ChecklistItem[]\n  cleaningTasks         CleaningTask[]\n  maintenanceTickets    MaintenanceTicket[]\n  notifications         Notification[]\n  aiAssistantMessages   AIAssistantMessage[]\n  apartmentAttachments  ApartmentAttachment[]\n  supervisors           ApartmentSupervisor[]\n  owners                ApartmentOwner[]\n  products              ApartmentProduct[]\n  checkinChecklistItems CheckinChecklistItem[]\n  checkinTasks          CheckinTask[]\n  engagements           EngagementApartment[]\n\n  @@index([organizationId])\n  @@index([propertyId])\n  @@index([unitCategoryId])\n}\n\nmodel ChecklistItem {\n  id                String    @id @default(uuid())\n  apartmentId       String\n  label             String\n  labelTranslations Json?\n  required          Boolean   @default(true)\n  photoRequired     Boolean   @default(false)\n  phase             String    @default(\"cleaning\")\n  answerType        String    @default(\"check\")\n  order             Int       @default(0)\n  createdAt         DateTime  @default(now())\n  formula           String?\n  type              String    @default(\"static\")\n  apartment         Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n}\n\nmodel Notification {\n  id          String     @id @default(uuid())\n  type        String\n  title       String\n  message     String\n  isRead      Boolean    @default(false)\n  readAt      DateTime?\n  createdAt   DateTime   @default(now())\n  apartmentId String?\n  apartment   Apartment? @relation(fields: [apartmentId], references: [id])\n}\n\nmodel Booking {\n  id                 String        @id @default(uuid())\n  apartmentId        String\n  guestName          String?\n  totalGuests        Int\n  checkInDate        DateTime\n  checkOutDate       DateTime\n  status             String?\n  externalId         String?       @unique\n  source             String?\n  cullaRequested     Boolean       @default(false)\n  productsConsumedAt DateTime?\n  createdAt          DateTime      @default(now())\n  apartment          Apartment     @relation(fields: [apartmentId], references: [id])\n  cleaningTask       CleaningTask?\n  checkinTask        CheckinTask?\n}\n\nmodel CleaningTask {\n  id                           String                @id @default(uuid())\n  apartmentId                  String\n  date                         DateTime\n  status                       String\n  createdAt                    DateTime              @default(now())\n  startedAt                    DateTime?\n  completedAt                  DateTime?\n  productsConsumedAt           DateTime?\n  skipProductConsumption       Boolean               @default(false)\n  assignedToId                 String?\n  notes                        String?\n  bookingId                    String?               @unique\n  booking                      Booking?              @relation(fields: [bookingId], references: [id])\n  checklistProgress            Json?                 @default(\"[]\")\n  correctionProgress           Json?\n  cleaningAccessToken          String?               @unique\n  cleaningAccessTokenExpiresAt DateTime?\n  cullaRequested               Boolean               @default(false)\n  sofaBedForced                Boolean               @default(false)\n  totalGuests                  Int?\n  apartment                    Apartment             @relation(fields: [apartmentId], references: [id])\n  assignedTo                   User?                 @relation(fields: [assignedToId], references: [id])\n  messages                     CleaningTaskMessage[]\n  attachments                  Attachment[]\n  aiAssistantMessages          AIAssistantMessage[]\n  supervisorReviews            SupervisorReview[]\n}\n\n// Voce della checklist di CHECK-IN, per-appartamento. Modello separato dalle\n// pulizie (ChecklistItem) per isolamento totale tra le due liste.\nmodel CheckinChecklistItem {\n  id                String    @id @default(uuid())\n  apartmentId       String\n  label             String\n  labelTranslations Json?\n  required          Boolean   @default(true)\n  photoRequired     Boolean   @default(false)\n  order             Int       @default(0)\n  createdAt         DateTime  @default(now())\n  type              String    @default(\"static\")\n  apartment         Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n}\n\n// Task operativa di CHECK-IN, gemella di CleaningTask ma agganciata alla data\n// di check-in della prenotazione. Auto-creata da ogni prenotazione.\nmodel CheckinTask {\n  id                          String               @id @default(uuid())\n  apartmentId                 String\n  date                        DateTime\n  status                      String\n  createdAt                   DateTime             @default(now())\n  startedAt                   DateTime?\n  completedAt                 DateTime?\n  assignedToId                String?\n  notes                       String?\n  bookingId                   String?              @unique\n  booking                     Booking?             @relation(fields: [bookingId], references: [id])\n  checklistProgress           Json?                @default(\"[]\")\n  checkinAccessToken          String?              @unique\n  checkinAccessTokenExpiresAt DateTime?\n  apartment                   Apartment            @relation(fields: [apartmentId], references: [id])\n  assignedTo                  User?                @relation(fields: [assignedToId], references: [id])\n  messages                    CheckinTaskMessage[]\n  attachments                 Attachment[]\n}\n\nmodel CheckinTaskMessage {\n  id              String      @id @default(uuid())\n  text            String?\n  role            String\n  senderName      String\n  createdAt       DateTime    @default(now())\n  checkinTaskId   String\n  checkinTask     CheckinTask @relation(fields: [checkinTaskId], references: [id], onDelete: Cascade)\n  attachmentId    String?\n  attachment      Attachment? @relation(fields: [attachmentId], references: [id])\n  readByManagerAt DateTime?\n  readByWorkerAt  DateTime?\n}\n\nmodel MaintenanceTicket {\n  id                              String                   @id @default(uuid())\n  apartmentId                     String\n  title                           String\n  description                     String\n  status                          String\n  priority                        String\n  createdAt                       DateTime                 @default(now())\n  assignedToId                    String?\n  scheduledStart                  DateTime?\n  scheduledEnd                    DateTime?\n  startedAt                       DateTime?\n  resolvedAt                      DateTime?\n  correctionProgress              Json?\n  maintenanceTasks                Json?\n  maintenanceAccessToken          String?                  @unique\n  maintenanceAccessTokenExpiresAt DateTime?\n  apartment                       Apartment                @relation(fields: [apartmentId], references: [id])\n  assignedTo                      User?                    @relation(fields: [assignedToId], references: [id])\n  attachments                     Attachment[]\n  messages                        Message[]\n  aiAssistantMessages             AIAssistantMessage[]\n  supervisorReviews               SupervisorReview[]\n  dateRequests                    MaintenanceDateRequest[]\n}\n\n// Richiesta (dall'impresa al proprietario) di spostare la data di un intervento.\n// Diventa effettiva solo dopo l'approvazione del manager dell'organizzazione.\nmodel MaintenanceDateRequest {\n  id                  String            @id @default(uuid())\n  maintenanceTicketId String\n  companyId           String\n  requestedByUserId   String?\n  proposedStart       DateTime\n  proposedEnd         DateTime?\n  reason              String?\n  status              String            @default(\"PENDING\") // PENDING | APPROVED | REJECTED\n  createdAt           DateTime          @default(now())\n  resolvedAt          DateTime?\n  resolvedByUserId    String?\n  maintenanceTicket   MaintenanceTicket @relation(fields: [maintenanceTicketId], references: [id], onDelete: Cascade)\n\n  @@index([maintenanceTicketId])\n  @@index([status])\n  @@index([companyId])\n}\n\nmodel AIAssistantMessage {\n  id                  String                 @id @default(uuid())\n  role                AIAssistantMessageRole\n  content             String\n  userRole            Role\n  apartmentId         String?\n  cleaningTaskId      String?\n  maintenanceTicketId String?\n  createdAt           DateTime               @default(now())\n  apartment           Apartment?             @relation(fields: [apartmentId], references: [id], onDelete: SetNull)\n  cleaningTask        CleaningTask?          @relation(fields: [cleaningTaskId], references: [id], onDelete: Cascade)\n  maintenanceTicket   MaintenanceTicket?     @relation(fields: [maintenanceTicketId], references: [id], onDelete: Cascade)\n\n  @@index([apartmentId])\n  @@index([cleaningTaskId])\n  @@index([maintenanceTicketId])\n  @@index([createdAt])\n}\n\nmodel Attachment {\n  id                  String                @id @default(uuid())\n  url                 String\n  fileName            String                @default(\"attachment\")\n  fileType            String?\n  size                Int?\n  category            String                @default(\"OTHER\")\n  extractedText       String?\n  createdAt           DateTime              @default(now())\n  maintenanceTicketId String?\n  maintenanceTicket   MaintenanceTicket?    @relation(fields: [maintenanceTicketId], references: [id], onDelete: Cascade)\n  cleaningTaskId      String?\n  cleaningTask        CleaningTask?         @relation(fields: [cleaningTaskId], references: [id], onDelete: Cascade)\n  checkinTaskId       String?\n  checkinTask         CheckinTask?          @relation(fields: [checkinTaskId], references: [id], onDelete: Cascade)\n  messages            Message[]\n  cleaningMessages    CleaningTaskMessage[]\n  checkinMessages     CheckinTaskMessage[]\n\n  @@index([maintenanceTicketId])\n  @@index([cleaningTaskId])\n  @@index([checkinTaskId])\n  @@index([category])\n}\n\nmodel ApartmentAttachment {\n  id            String    @id @default(uuid())\n  apartmentId   String\n  apartment     Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n  filename      String\n  url           String?\n  mimeType      String?\n  size          Int?\n  category      String    @default(\"OTHER\")\n  linkedTo      String?\n  extractedText String?\n  notes         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([apartmentId])\n  @@index([category])\n}\n\nmodel Message {\n  id                  String            @id @default(uuid())\n  text                String?\n  role                String\n  senderName          String\n  createdAt           DateTime          @default(now())\n  maintenanceTicketId String\n  maintenanceTicket   MaintenanceTicket @relation(fields: [maintenanceTicketId], references: [id], onDelete: Cascade)\n  attachmentId        String?\n  attachment          Attachment?       @relation(fields: [attachmentId], references: [id])\n  readByManagerAt     DateTime?\n  readByWorkerAt      DateTime?\n}\n\nmodel CleaningTaskMessage {\n  id              String       @id @default(uuid())\n  text            String?\n  role            String\n  senderName      String\n  createdAt       DateTime     @default(now())\n  cleaningTaskId  String\n  cleaningTask    CleaningTask @relation(fields: [cleaningTaskId], references: [id], onDelete: Cascade)\n  attachmentId    String?\n  attachment      Attachment?  @relation(fields: [attachmentId], references: [id])\n  readByManagerAt DateTime?\n  readByWorkerAt  DateTime?\n}\n\nmodel SupervisorReview {\n  id                  String             @id @default(uuid())\n  supervisorId        String\n  supervisor          User               @relation(\"SupervisorReviews\", fields: [supervisorId], references: [id])\n  cleaningTaskId      String?\n  cleaningTask        CleaningTask?      @relation(fields: [cleaningTaskId], references: [id], onDelete: Cascade)\n  maintenanceTicketId String?\n  maintenanceTicket   MaintenanceTicket? @relation(fields: [maintenanceTicketId], references: [id], onDelete: Cascade)\n  decision            String\n  notes               String?\n  correctionItems     Json?\n  createdAt           DateTime           @default(now())\n\n  @@index([cleaningTaskId])\n  @@index([maintenanceTicketId])\n  @@index([supervisorId])\n}\n\nmodel ApartmentSupervisor {\n  apartmentId String\n  userId      String\n  apartment   Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@id([apartmentId, userId])\n}\n\n// Anagrafica clienti/proprietari per la fatturazione (privato o impresa).\n// Org-scoped. Un cliente può avere più appartamenti; ogni appartamento ha\n// al massimo un cliente (Apartment.clientId).\nmodel Client {\n  id             String      @id @default(uuid())\n  organizationId String\n  type           String      @default(\"PRIVATE\") // PRIVATE | COMPANY\n  name           String // ragione sociale (impresa) o nome e cognome (privato)\n  vatNumber      String? // partita IVA\n  taxCode        String? // codice fiscale\n  sdiCode        String? // codice destinatario SDI\n  pec            String?\n  email          String?\n  phone          String?\n  address        String?\n  city           String?\n  zip            String?\n  province       String?\n  country        String?     @default(\"Italia\")\n  notes          String?\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n  apartments     Apartment[]\n\n  @@index([organizationId])\n}\n\nmodel ApartmentOwner {\n  apartmentId String\n  userId      String\n  apartment   Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@id([apartmentId, userId])\n}\n\nmodel ManagerChatSession {\n  id             String               @id @default(uuid())\n  date           DateTime             @db.Date\n  createdAt      DateTime             @default(now())\n  organizationId String?\n  organization   Organization?        @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  messages       ManagerChatMessage[]\n\n  @@unique([date, organizationId])\n  @@index([organizationId])\n}\n\nmodel ManagerChatMessage {\n  id        String             @id @default(uuid())\n  sessionId String\n  session   ManagerChatSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  role      String\n  content   String\n  createdAt DateTime           @default(now())\n\n  @@index([sessionId])\n}\n\nenum Role {\n  MANAGER\n  CLEANER\n  MAINTENANCE\n  SUPERVISOR\n  OWNER\n  CHECKIN\n}\n\nenum AIAssistantMessageRole {\n  USER\n  ASSISTANT\n}\n\nmodel PushSubscription {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\nmodel ApnsToken {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\nmodel FcmToken {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\nmodel CleanerLocation {\n  id        String   @id @default(uuid())\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  latitude  Float\n  longitude Float\n  accuracy  Float?\n  updatedAt DateTime @updatedAt\n}\n\nmodel SuperAdminLog {\n  id        String   @id @default(cuid())\n  action    String\n  detail    String?\n  orgId     String?\n  orgName   String?\n  ip        String?\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([orgId])\n}\n\nmodel ApartmentProduct {\n  id               String    @id @default(uuid())\n  apartmentId      String\n  apartment        Apartment @relation(fields: [apartmentId], references: [id], onDelete: Cascade)\n  name             String\n  emoji            String    @default(\"📦\")\n  unit             String    @default(\"pz\")\n  stock            Int       @default(0)\n  minStock         Int       @default(0)\n  consumptionType  String    @default(\"STATIC\")\n  consumptionValue Float     @default(1)\n  price            Float     @default(0) // prezzo per unità (imponibile)\n  vat              Float     @default(22) // aliquota IVA in %\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  movements StockMovement[]\n\n  @@index([apartmentId])\n}\n\n// Registro movimenti di scorta: una riga per ogni variazione (consumo al\n// check-in, rifornimento, rettifica manuale, valore iniziale). Consente lo\n// storico per intervallo di date (quantità iniziale/finale + dettaglio).\nmodel StockMovement {\n  id        String           @id @default(uuid())\n  productId String\n  product   ApartmentProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n  delta     Int // variazione (negativa = consumo, positiva = carico)\n  balance   Int // saldo risultante dopo questo movimento\n  reason    String // INITIAL | CHECKIN | RESTOCK | ADJUSTMENT\n  bookingId String? // riferimento prenotazione (per i consumi da check-in)\n  note      String? // etichetta leggibile (es. nome ospite)\n  createdAt DateTime         @default(now())\n\n  @@index([productId, createdAt])\n}\n\n// Prodotto di MAGAZZINO: scorta generica a livello di organizzazione (non legata\n// a un singolo appartamento). Es. impresa di pulizie con materiale di consumo.\n// Consumo: MANUAL (solo \"Preleva\"), STATIC (fisso per check-in), DYNAMIC\n// (valore × base BATHROOM/GUEST/BEDROOM per ogni check-in del giorno).\nmodel WarehouseProduct {\n  id               String   @id @default(uuid())\n  organizationId   String? // proprietario = Organization OPPURE Company (uno solo)\n  companyId        String?\n  name             String\n  emoji            String   @default(\"📦\")\n  unit             String   @default(\"pz\")\n  stock            Int      @default(0)\n  minStock         Int      @default(0)\n  consumptionType  String   @default(\"MANUAL\") // MANUAL | STATIC | DYNAMIC\n  consumptionBasis String   @default(\"BATHROOM\") // usato solo se DYNAMIC: BATHROOM | GUEST | BEDROOM\n  consumptionValue Float    @default(1)\n  price            Float    @default(0) // prezzo per unità (imponibile)\n  vat              Float    @default(22) // aliquota IVA in %\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  company   Company?                 @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  movements WarehouseStockMovement[]\n\n  @@index([organizationId])\n  @@index([companyId])\n}\n\n// Registro movimenti del magazzino (analogo a StockMovement per gli appartamenti).\nmodel WarehouseStockMovement {\n  id        String           @id @default(uuid())\n  productId String\n  product   WarehouseProduct @relation(fields: [productId], references: [id], onDelete: Cascade)\n  delta     Int\n  balance   Int\n  reason    String // INITIAL | CHECKIN | RESTOCK | ADJUSTMENT | USAGE\n  bookingId String?\n  note      String?\n  createdAt DateTime         @default(now())\n\n  @@index([productId, createdAt])\n}\n"
}

